async function runPdf() { if (operation.value === 'images-to-pdf') { const images = files.value.filter((file) => file.type.startsWith('image/')); if (!images.length) throw new Error('请选择至少一张图片。'); const output = await PDFDocument.create(); for (const file of images) { const image = await imageToPng(file); const embedded = await output.embedPng(image.data); const page = output.addPage([image.width, image.height]); page.drawImage(embedded, { x: 0, y: 0, width: image.width, height: image.height }) } const name = `${outputName.value || 'toolknit'}-images.pdf`; download(name, bytes(await output.save()), 'application/pdf'); return [name] } const pdfs = files.value.filter((file) => file.type === 'application/pdf' || file.name.endsWith('.pdf')); if (!pdfs.length) throw new Error('请选择至少一份 PDF。'); if (operation.value === 'merge') { const output = await PDFDocument.create(); for (const file of pdfs) { const source = await PDFDocument.load(await file.arrayBuffer()); const pages = await output.copyPages(source, source.getPageIndices()); pages.forEach((page) => output.addPage(page)) } download(`${outputName.value || 'toolknit'}-merged.pdf`, bytes(await output.save()), 'application/pdf'); return [`${outputName.value || 'toolknit'}-merged.pdf`] }
