  const source = await PDFDocument.load(await pdfs[0].arrayBuffer()); const indexes = pageIndexes(pageRange.value, source.getPageCount()); if (!indexes.length) throw new Error('页码范围无效，例如：1,3-5。'); const output = await PDFDocument.create(); const pages = await output.copyPages(source, indexes); pages.forEach((page) => output.addPage(page)); const suffix = operation.value === 'reorder' ? 'reordered' : 'extract'; const name = `${cleanName(pdfs[0].name)}-${suffix}.pdf`; download(name, bytes(await output.save()), 'application/pdf'); return [name]
}
async function runImage() { const inputs = files.value.filter((file) => file.type.startsWith('image/')); if (!inputs.length) throw new Error('请选择至少一张图片。'); const ext = imageFormat.value === 'image/jpeg' ? 'jpg' : imageFormat.value.split('/')[1]; const names: string[] = []; for (const file of inputs) { const blob = await imageToBlob(file); const name = `${cleanName(file.name)}-toolknit.${ext}`; download(name, blob, imageFormat.value); names.push(name) } return names }
async function runText() { const raw = textInput.value || (files.value[0] ? await files.value[0].text() : ''); if (!raw.trim()) throw new Error('粘贴文本或选择一个文本文件。'); let output = raw; let extension = 'txt'; if (textMode.value === 'json') { output = JSON.stringify(JSON.parse(raw), null, 2); extension = 'json' } else if (textMode.value === 'trim') output = raw.split('\n').map((line) => line.trimEnd()).filter((line, index, list) => line || list[index - 1]).join('\n').trim() + '\n'; else { output = raw.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim() + '\n'; extension = 'md' } const name = `${outputName.value || 'toolknit'}-clean.${extension}`; download(name, output, `text/${extension};charset=utf-8`); return [name] }
async function runOrganize() { if (!files.value.length) throw new Error('请选择至少一个文件。'); if (operation.value === 'rename-report') { const lines = files.value.map((file, index) => `${file.name}  →  ${renamePrefix.value || '整理文件'}-${String(index + 1).padStart(3, '0')}${file.name.includes('.') ? `.${file.name.split('.').pop()}` : ''}`); const name = `${outputName.value || 'toolknit'}-rename-preview.txt`; download(name, lines.join('\n'), 'text/plain;charset=utf-8'); return [name] } const map = new Map<string, string[]>(); for (const file of files.value) { const digest = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', await file.arrayBuffer()))).map((value) => value.toString(16).padStart(2, '0')).join(''); map.set(digest, [...(map.get(digest) ?? []), file.name]) } const duplicates = [...map.values()].filter((items) => items.length > 1); const name = `${outputName.value || 'toolknit'}-dedupe-report.txt`; download(name, duplicates.length ? duplicates.map((items) => items.join('  =  ')).join('\n') : '未发现重复文件。', 'text/plain;charset=utf-8'); return [name] }
async function run() { if (!files.value.length && !(group.value === 'text' && textInput.value.trim())) { message.value = '请先选择输入文件。'; return } running.value = true; const kind = group.value as 'pdf' | 'image' | 'text' | 'archive'; const job = store.addJob(kind, `${groups.find((item) => item[0] === group.value)?.[1]} · ${operations.value.find((item) => item[0] === operation.value)?.[1]}`, files.value.map((file) => file.name)); store.updateJob(job.id, { status: 'running', progress: 15, detail: '正在准备输入文件…' }); try { const outputNames = group.value === 'pdf' ? await runPdf() : group.value === 'image' ? await runImage() : group.value === 'text' ? await runText() : await runOrganize(); store.updateJob(job.id, { status: 'succeeded', progress: 100, outputNames, detail: '已生成新输出，原文件未修改。' }); message.value = `任务完成：已生成 ${outputNames.length} 个输出文件。` } catch (error) { const detail = error instanceof Error ? error.message : '工具执行失败。'; store.updateJob(job.id, { status: 'failed', progress: 100, errorCode: 'TOOL_EXECUTION_FAILED', detail }); message.value = detail } finally { running.value = false } }
